@using sv_64b9fda40467412d97b34111c869dff6.Services

<div class="message-area">
    <div class="area-header">
        <h6># @ChannelName</h6>
        <span class="area-description">@ChannelDescription</span>
    </div>

    <div class="message-list" @onscroll="HandleScroll" @ref="_messageListRef">
        @if (_isLoadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }

        @foreach (var msg in Messages)
        {
            <MessageItem Message="msg"
                         ThreadReplyCount="GetThreadReplyCount(msg.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <div class="message-input-area">
        <textarea class="message-textarea"
                  placeholder="Message #@ChannelName"
                  @bind="_newMessageText"
                  @onkeydown="HandleKeyDown"
                  rows="2"></textarea>
        <button class="send-btn" @onclick="SendMessage" disabled="@string.IsNullOrWhiteSpace(_newMessageText)">
            Send
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private string _newMessageText = "";
    private bool _isLoadingMore;
    private ElementReference _messageListRef;

    private int GetThreadReplyCount(int messageId)
    {
        return ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId)?.ReplyCount ?? 0;
    }

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers load more (handled via JS interop for scroll position)
        // Simplified: the parent handles pagination state
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessage();
        }
    }

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText)) return;
        var text = _newMessageText;
        _newMessageText = "";
        await OnSendMessage.InvokeAsync(text);
    }

    public async Task OnScrollToTop()
    {
        if (_isLoadingMore) return;
        _isLoadingMore = true;
        await OnLoadMore.InvokeAsync();
        _isLoadingMore = false;
    }
}

